def fires(b):
    empty = sum(1 for h in b.heights if h == 0)
    full = sum(1 for h in b.heights if h == 6)
    return full == 0 and empty >= 2 and b.ply >= 6

def level(b):
    empty = sum(1 for h in b.heights if h == 0)
    full = sum(1 for h in b.heights if h == 6)
    s = 0
    if full == 0:
        s += 2
    s += min(empty, 3)
    if len(b.their_playable_wins) > 0:
        s += 2
    return min(9, s)

def early_points(b):
    empty = sum(1 for h in b.heights if h == 0)
    full = sum(1 for h in b.heights if h == 6)
    s = 0
    if b.ply <= 8:
        s += 3
    elif b.ply <= 14:
        s += 2
    elif b.ply <= 20:
        s += 1
    s += min(empty, 3)
    s -= 2 * full
    if b.heights[3] <= 2:
        s += 1
    return s

def fires(b):
    return early_points(b) >= 7

def level(b):
    return max(0, min(9, early_points(b) + 1))

def well_depth(b):
    h = b.heights
    best = 0
    for c in range(7):
        left = h[c - 1] if c > 0 else 0
        right = h[c + 1] if c < 6 else 0
        d = min(left, right) - h[c] if 0 < c < 6 else 0
        best = max(best, d)
    return best

def fires(b):
    full = sum(1 for x in b.heights if x == 6)
    return full == 0 and well_depth(b) >= 2

def level(b):
    full = sum(1 for x in b.heights if x == 6)
    s = 2 * well_depth(b) - 2 * full
    return max(0, min(9, s))
